import java.util.*;class TaskModel{String name;TaskModel(String n){name=n;}}class TaskService{List<TaskModel> items=new ArrayList<>();void add(String n){if(n==null||n.isBlank())throw new IllegalArgumentException("Name required");items.add(new TaskModel(n));}int count(){return items.size();}}public class LayeredApp{public static void main(String[]x){TaskService s=new TaskService();s.add("Finish Java practical");s.add("Revise OOP");System.out.println("Tasks="+s.count());}}
